import{_ as s,l,o as a,c,v as o,p as i,x as r,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"系统调用 ABI","description":"","frontmatter":{"title":"系统调用 ABI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syscall-abi.md","filePath":"cs/syscall-abi.md","lastUpdated":1789023840000}'),h={name:"cs/syscall-abi.md"};function m(A,e,B,_,u,E){const t=l("Mermaid");return a(),c("div",null,[e[1]||(e[1]=o('<h1 id="系统调用-abi" tabindex="-1">系统调用 ABI <a class="header-anchor" href="#系统调用-abi" aria-label="Permalink to &quot;系统调用 ABI&quot;">​</a></h1><div class="epigraph"><p>系统调用号、参数寄存器与返回值约定一旦钉死，用户库与内核才能各自演进而不把对方拆掉。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/kernel-user">上一课</a>命名了门：用户只能陷入，不能跳进内核任意地址。<a href="/cs/privilege-rings">特权级</a>禁止用户执行特权指令。<a href="/cs/calling-convention-stack">调用约定</a>只覆盖 <code>jal</code> 那一套。缺口是：陷入时<strong>哪一个寄存器是调用号、参数放哪、错误怎么回来</strong>——这是系统调用 ABI，还不是整条内核路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每个程序自己发明「<code>a0</code> 里是路径字符串」，内核无法分发。硬件只保证切特权、跳到<a href="/cs/exception-interrupt-entry">异常入口</a>；软件必须再约定：调用号、至多若干个寄存器参数、返回值与错误码的编码。缺口不是再讲环，而是把普通过程 ABI 换成<strong>跨特权的那一张表</strong>。</p><p>本课不列出 Linux 的全部调用号，也不把 <code>ioctl</code> 的设备语义写完。</p><p><span class="marginnote">libc 的 <code>read</code> 仍是用户函数；真正遵守本课约定的是最里一层陷入指令。POSIX 是接口名，ABI 是寄存器与编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户：把调用号放入约定寄存器（或立即数槽），参数按序放入其余约定位置，执行陷入指令。内核入口：按号查表，从那些寄存器读参数。成功则返回值在约定寄存器；失败则把错误码放进约定位置（或负值约定），用户库再译成 <code>errno</code>。</p>',9)),(a(),i(p,null,{default:r(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E7%94%A8%E6%88%B7%E5%BA%93%22%5D%20--%3E%20ABI%5B%22%E8%B0%83%E7%94%A8%E5%8F%B7%E4%B8%8E%E5%8F%82%E6%95%B0%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20ABI%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%E6%8C%87%E4%BB%A4%22%5D%0A%20%20TRAP%20--%3E%20DISP%5B%22%E5%86%85%E6%A0%B8%E6%8C%89%E5%8F%B7%E5%88%86%E5%8F%91%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>同一套 ABI 对所有自愿服务有效：后课的 <code>fork</code>、<code>mmap</code> 只是表上的不同号。本课只钉约定，不走拷贝与阻塞。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ABI 把「请内核办事」收成可版本化的合同。用户永远不持有内核函数地址；它只持有编号。换内核实现不必重编用户程序，只要编号与寄存器槽不变。这与普通 <code>call</code> 不同：目标不在用户可写的 GOT 里。</p><p>参数仍可能是用户指针。ABI 只说「指针值在哪个寄存器」；指针指向的页是否可读、要不要拷贝，是<a href="/cs/syscall-path">系统调用路径</a>之后、下一课之前仍未展开的缺口——本课不提前做 <code>copy_from_user</code>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不对比 <code>int 0x80</code>、<code>syscall</code>、<code>svc</code> 的编码字节，不把 seccomp 写成安全课。也不讨论把读时钟留在用户态：那是下一课 vDSO，不改变「改内核状态必须遵守本课 ABI 并陷入」。</p><p>调用号空间与 libc 版本绑定；兼容层是发行策略，不是另一套操作系统课。</p><p>后课默认：用户要服务，先按 ABI 填号与参数。有些只读查询能否免一次陷入，下一课讲 vDSO。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>系统调用 ABI：调用号、参数槽、返回值与错误约定。</li><li>用户只持有编号，不持有内核指令指针。</li><li>指针参数的安全拷贝仍未给出。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Love, <em>Linux Kernel Development</em>。</li></ul>',10))])}const I=s(h,[["render",m]]);export{b as __pageData,I as default};
